+import { renderHook } from '@testing-library/react';
+
+import { type DataSourceInstanceListItem, type DataSourcePluginMeta } from '@grafana/data';
+
+import {
+  getDefaultDataSourceInstanceListItemFromList,
+  useDefaultDataSourceInstanceListItem,
+} from './defaultInstance';
+
+function item(overrides: Partial<DataSourceInstanceListItem> & { builtIn?: boolean }): DataSourceInstanceListItem {
+  const { builtIn, ...rest } = overrides;
+  return {
+    uid: 'uid',
+    name: 'name',
+    type: 'prometheus',
+    isDefault: false,
+    meta: { id: rest.type ?? 'prometheus', builtIn } as DataSourcePluginMeta,
+    ...rest,
+  };
+}
+
+const grafana = item({ uid: 'grafana', name: '-- Grafana --', type: 'grafana', builtIn: true });
+const loki = item({ uid: 'loki', name: 'Loki', type: 'loki', isDefault: true });
+const promA = item({ uid: 'prom-a', name: 'Prom A' });
+const promB = item({ uid: 'prom-b', name: 'Prom B' });
+
+describe('getDefaultDataSourceInstanceListItemFromList', () => {
+  it('returns the organization default from the full list', () => {
+    expect(getDefaultDataSourceInstanceListItemFromList([grafana, promA, loki, promB])).toBe(loki);
+  });
+
+  it('returns the first instance of a subset that does not contain the organization default', () => {
+    expect(getDefaultDataSourceInstanceListItemFromList([promA, promB])).toBe(promA);
+  });
+
+  it('prefers a non built-in instance when no default is flagged', () => {
+    expect(getDefaultDataSourceInstanceListItemFromList([grafana, promB])).toBe(promB);
+  });
+
+  it('falls back to a built-in instance when it is the only option', () => {
+    expect(getDefaultDataSourceInstanceListItemFromList([grafana])).toBe(grafana);
+  });
+
+  it('returns undefined for an empty or missing list', () => {
+    expect(getDefaultDataSourceInstanceListItemFromList([])).toBeUndefined();
+    expect(getDefaultDataSourceInstanceListItemFromList(undefined)).toBeUndefined();
+  });
+});
+
+describe('useDefaultDataSourceInstanceListItem', () => {
+  it('resolves the default from the given list and updates when the list changes', () => {
+    const { result, rerender } = renderHook(({ items }) => useDefaultDataSourceInstanceListItem(items), {
+      initialProps: { items: [promA, loki] },
+    });
+    expect(result.current).toBe(loki);
+
+    rerender({ items: [promB, promA] });
+    expect(result.current).toBe(promB);
+  });
+});
