+import { useMemo } from 'react';
+
+import { type DataSourceInstanceListItem } from '@grafana/data';
+
+/**
+ * Pick the default data source from a list of data source instances.
+ *
+ * Resolution order:
+ * 1. The instance flagged `isDefault` (the organization default), if it is in the list.
+ * 2. Otherwise the first instance that is not a built-in data source
+ *    (`-- Grafana --`, `-- Mixed --`, `-- Dashboard --`).
+ * 3. Otherwise the first instance in the list.
+ *
+ * Passing the full list returns the organization default; passing a filtered list
+ * (e.g. only Prometheus instances) returns the best default within that subset. Returns
+ * `undefined` for an empty list.
+ *
+ * This is a plain function: it does not load data sources and can be called outside of
+ * React rendering. Use {@link useDefaultDataSourceInstanceListItem} inside components.
+ *
+ * @public
+ */
+export function getDefaultDataSourceInstanceListItemFromList(
+  items: readonly DataSourceInstanceListItem[] | null | undefined
+): DataSourceInstanceListItem | undefined {
+  if (!items?.length) {
+    return undefined;
+  }
+  return items.find((item) => item.isDefault) ?? items.find((item) => !item.meta?.builtIn) ?? items[0];
+}
+
+/**
+ * React hook form of {@link getDefaultDataSourceInstanceListItemFromList}. Recomputes only
+ * when the `items` array reference changes; it does not load data sources itself, so pair it
+ * with a list you already have (for example from `useDataSourceInstanceList`).
+ *
+ * @public
+ */
+export function useDefaultDataSourceInstanceListItem(
+  items: readonly DataSourceInstanceListItem[] | null | undefined
+): DataSourceInstanceListItem | undefined {
+  return useMemo(() => getDefaultDataSourceInstanceListItemFromList(items), [items]);
+}
